css.fulfillment-workbench.css:
.dmwcfw-launcher {
	align-items: center;
	background:
		radial-gradient(
			circle at 50% 0%,
			rgb(150 88 203 / 18%),
			transparent 55%
		),
		var(--desktop-mode-surface, #fff);
	box-sizing: border-box;
	display: flex;
	flex-direction: column;
	gap: 14px;
	height: 100%;
	justify-content: center;
	padding: 32px;
	text-align: center;
}

.dmwcfw-launcher__icon {
	align-items: center;
	background: #96588a;
	border-radius: 18px;
	box-shadow: 0 12px 30px rgb(85 45 77 / 24%);
	color: #fff;
	display: flex;
	height: 68px;
	justify-content: center;
	width: 68px;
}

.dmwcfw-launcher__icon .dashicons {
	font-size: 36px;
	height: 36px;
	width: 36px;
}

.dmwcfw-launcher h2,
.dmwcfw-launcher p {
	margin: 0;
}

.dmwcfw-launcher h2 {
	color: var(--desktop-mode-text, #1e1e1e);
	font-size: 22px;
	line-height: 1.2;
}

.dmwcfw-launcher__status {
	color: var(--desktop-mode-text-muted, #646970);
	font-size: 14px;
	line-height: 1.5;
	max-width: 330px;
}

@media (max-width: 480px), (max-height: 360px) {
	.dmwcfw-launcher {
		gap: 10px;
		padding: 20px;
	}

	.dmwcfw-launcher__icon {
		border-radius: 14px;
		height: 52px;
		width: 52px;
	}

	.dmwcfw-launcher__icon .dashicons {
		font-size: 28px;
		height: 28px;
		width: 28px;
	}
}

@media (prefers-reduced-motion: reduce) {
	.dmwcfw-launcher__icon {
		box-shadow: none;
	}
}

js.fulfillment-workbench.js:
(function() {
  "use strict";
  function desktopForWindow(win, desktops, fallbackId) {
    const configured = win.config.desktopId;
    return configured && desktops.some((desktop) => desktop.id === configured) ? configured : fallbackId;
  }
  function reusableWindow(windows, desktops, baseId, fallbackId) {
    const candidates = windows.map((win) => ({
      window: win,
      desktopId: desktopForWindow(win, desktops, fallbackId)
    })).filter(
      (candidate) => desktops.some((desktop) => desktop.id === candidate.desktopId)
    );
    if (candidates.length === 0) {
      return null;
    }
    return candidates.find((candidate) => candidate.window.id === baseId) ?? candidates[candidates.length - 1];
  }
  async function launchWorkbench(api2, config) {
    if (!config.id || !config.url || !config.desktopLabel) {
      throw new Error("The fulfillment workbench configuration is unavailable.");
    }
    const manager = api2.windowManager;
    const activeBefore = manager.getActiveDesktopId();
    const desktops = manager.getDesktops();
    const existing = reusableWindow(
      manager.getAllByBaseId(config.id),
      desktops,
      config.id,
      activeBefore
    );
    if (existing) {
      manager.switchDesktop(existing.desktopId);
      if (existing.window.state === "minimized") {
        existing.window.restore();
      }
      manager.focus(existing.window);
      return {
        desktopId: existing.desktopId,
        createdDesktop: false,
        opened: false,
        reused: true
      };
    }
    let desktop = desktops.find(
      (candidate) => candidate.label === config.desktopLabel
    );
    const createdDesktop = !desktop;
    if (!desktop) {
      desktop = manager.createDesktop();
      desktop.label = config.desktopLabel;
    }
    manager.switchDesktop(desktop.id);
    try {
      await manager.open({
        id: config.id,
        baseId: config.id,
        url: config.url,
        parentUrl: config.url,
        title: config.title,
        icon: config.icon,
        initialState: "maximized",
        submenu: config.submenu
      });
    } catch (error) {
      manager.switchDesktop(activeBefore);
      if (createdDesktop) {
        manager.closeDesktop(desktop.id);
      }
      throw error;
    }
    api2.saveSession?.();
    return {
      desktopId: desktop.id,
      createdDesktop,
      opened: true,
      reused: false
    };
  }
  function createWorkbenchLauncher(api2) {
    let inFlight = null;
    return (config) => {
      if (!inFlight) {
        inFlight = launchWorkbench(api2, config).finally(() => {
          inFlight = null;
        });
      }
      return inFlight;
    };
  }
  const LAUNCHER_ID = "desktop-mode-fulfillment-workbench-for-woocommerce";
  const COMMAND_OWNER = "desktop-mode-fulfillment-workbench-for-woocommerce";
  function translate(text) {
    return (
      // eslint-disable-next-line @wordpress/i18n-no-variables
      window.wp?.i18n?.__(
        text,
        "desktop-mode-fulfillment-workbench-for-woocommerce"
      ) ?? text
    );
  }
  function getConfig(api2) {
    const config = api2.getWindowConfig(LAUNCHER_ID);
    if (!config?.id || !config.desktopLabel || !config.url || !Array.isArray(config.submenu)) {
      throw new Error(
        translate("The fulfillment workbench configuration is unavailable.")
      );
    }
    return config;
  }
  function launcherWindowId(body) {
    const root = body.closest(".desktop-mode-window");
    return root?.id.replace(/^wp-window-/, "") ?? null;
  }
  function closeLauncherAndWait(body, api2) {
    const id = launcherWindowId(body);
    const launcher = id ? api2.windowManager.getById(id) : void 0;
    if (!id || !launcher) {
      return Promise.resolve();
    }
    return new Promise((resolve) => {
      let settled = false;
      const finish = () => {
        if (settled) {
          return;
        }
        settled = true;
        document.removeEventListener("desktop-mode-window-closed", onClosed);
        window.clearTimeout(timeout);
        resolve();
      };
      const onClosed = (event) => {
        const detail = event.detail;
        if (detail?.windowId === id) {
          finish();
        }
      };
      const timeout = window.setTimeout(finish, 500);
      document.addEventListener("desktop-mode-window-closed", onClosed);
      launcher.close();
    });
  }
  function setLoadingState(body) {
    const status = body.querySelector("[data-dmwcfw-status]");
    const spinner = body.querySelector("[data-dmwcfw-spinner]");
    const retry = body.querySelector("[data-dmwcfw-retry]");
    if (status) {
      status.textContent = translate("Opening your Processing orders queue…");
    }
    if (spinner) {
      spinner.hidden = false;
    }
    if (retry) {
      retry.hidden = true;
      retry.setAttribute("disabled", "");
    }
  }
  function setFailureState(body) {
    const status = body.querySelector("[data-dmwcfw-status]");
    const spinner = body.querySelector("[data-dmwcfw-spinner]");
    const retry = body.querySelector("[data-dmwcfw-retry]");
    if (status) {
      status.textContent = translate(
        "The workbench could not be opened. Check WooCommerce and try again."
      );
    }
    if (spinner) {
      spinner.hidden = true;
    }
    if (retry) {
      retry.hidden = false;
      retry.removeAttribute("disabled");
    }
  }
  function registerLauncher(api2, launch) {
    window.desktopModeNativeWindows = window.desktopModeNativeWindows ?? {};
    window.desktopModeNativeWindows[LAUNCHER_ID] = async (body) => {
      const retry = body.querySelector("[data-dmwcfw-retry]");
      const open = async () => {
        setLoadingState(body);
        try {
          await launch(getConfig(api2));
          await closeLauncherAndWait(body, api2);
        } catch {
          setFailureState(body);
        }
      };
      retry?.addEventListener("click", () => {
        void open();
      });
      await open();
    };
  }
  function registerCommand(api2, launch) {
    if (typeof api2.registerCommand !== "function") {
      return;
    }
    api2.registerCommand({
      slug: "woocommerce_fulfillment_workbench",
      label: translate("Open Fulfillment Workbench for WooCommerce"),
      description: translate(
        "Open one focused Processing orders queue and resume where you left off."
      ),
      icon: "dashicons-store",
      owner: COMMAND_OWNER,
      run: async (_args, ctx) => {
        try {
          await launch(getConfig(api2));
          ctx.close();
        } catch {
          return translate("The fulfillment workbench could not be opened.");
        }
      }
    });
  }
  function whenDesktopReady(api2, callback) {
    if (typeof api2.ready === "function") {
      api2.ready(callback);
      return;
    }
    if (typeof api2.whenReady === "function") {
      api2.whenReady(callback);
      return;
    }
    callback();
  }
  const api = window.wp?.desktop;
  if (api) {
    const launch = createWorkbenchLauncher(api);
    registerLauncher(api, launch);
    whenDesktopReady(api, () => registerCommand(api, launch));
  }
})();
